-- Radical Red 4.1 Showdown export for mGBA: the party and all 25 PC boxes as Showdown text that
-- pastes into hzla's Dynamic-Calc-Decomps calc (Radical Red data sets), plus Hidden Power types.
-- Load: Tools > Scripting > File > Load script, with the Radical Red 4.1 ROM running. Type
-- `export()` in the scripting console to refresh; the text also goes to logs/showdown.txt.
-- Names come from rr_calc_names.lua (same folder), generated by gen_calc_names.js.
--
-- Evidence (RR 4.1 code unless noted):
--   gPlayerParty 0x02024284, 6 x 100 bytes, unencrypted, substructures G A E M (see rr_state.lua):
--     species +0x20, item +0x22, exp +0x24, moves 4 x u16 +0x2C, EVs +0x38 (HP Atk Def Spe SpA
--     SpD), IV word +0x48 (5 bits each, same order; bit 30 egg, bit 31 hidden ability), level +0x54.
--   PC boxes: 25 box pointers at ROM 0x09148930 (CFRU sPokemonBoxPtrs), 30 x 58-byte compressed
--     Pokemon each: personality +0x00, OT ID +0x04, species +0x1C, item +0x1E, exp +0x20, moves
--     4 x 10 bits packed little-endian from +0x27, EVs +0x2C, IV word +0x36. Decoded on a copy of
--     rr.ss2 (CFRU include/new/pokemon_storage_system.h layout; the calc reads the same offsets).
--   Level of a boxed Pokemon: 0x0803E7FC, the highest level L in 1..250 with
--     exp table 0x0915514C [growth rate * 256 + L] (u32) <= exp; growth rate = base stats +0x13.
--   Nature: GetNature 0x08042E9C = personality % 25.
--   Hidden Power type: CalcMonHiddenPowerType 0x09083384, low IV bits (HP 1, Atk 2, Def 4, Spe 8,
--     SpA 16, SpD 32) * 15 / 63 + 1, + 1 more past Steel (8) to skip type 9.
--   Ability: GetMonAbility 0x09079808. Base stats *0x080001BC (28 bytes per species): hidden
--     ability +0x1A when IV bit 31 is set and it is not 0, else ability 2 +0x17 when the
--     personality is odd and it is not 0, else ability 1 +0x16. Then 0x090796BC:
--     - flag 0x942 set and 0x930 clear: the ability randomizer 0x09078148 (skipped when flag 0x1042
--       or 0x104B is set; see random_ability). 0x090796BC also requires the Pokemon to share an OT
--       ID with a party member or the battle not to be a trainer battle (0x0907797C); that holds
--       for the player's own Pokemon and outside battle, so it is not checked here.
--     - flag 0x1034 or 0x103C set and OT ID = the player's (SaveBlock2 +0xA): the remap
--       0x09079584 (REMAP below, transcribed from its assembly).
--   Flags 0x900-0x18FF: byte 0x0203B174 + (id - 0x900) / 8, bit id % 8 (0x090B8FB0).

local SCRIPT_DIR = debug.getinfo(1, "S").source:match("^@(.*/)") or "./"
package.path = SCRIPT_DIR .. "?.lua;" .. package.path
local Names = require("rr_calc_names")

local PARTY, PARTY_SIZE = 0x02024284, 100
local BOX_PTRS, BOX_COUNT, BOX_SLOTS, BOX_MON_SIZE = 0x09148930, 25, 30, 58
local BASE_STATS_PTR, BASE_SIZE = 0x080001BC, 28
local EXP_TABLE, MAX_LEVEL = 0x0915514C, 250
local SAVE_BLOCK2_PTR = 0x0300500C
local EXPANDED_FLAGS = 0x0203B174
local BATTLE_TYPE_FLAGS = 0x02022B4C

local NATURES = { [0] = "Hardy", "Lonely", "Brave", "Adamant", "Naughty", "Bold", "Docile", "Relaxed",
	"Impish", "Lax", "Timid", "Hasty", "Serious", "Jolly", "Naive", "Modest", "Mild", "Quiet",
	"Bashful", "Rash", "Calm", "Gentle", "Sassy", "Careful", "Quirky" }
local TYPES = { [0] = "Normal", "Fighting", "Flying", "Poison", "Ground", "Rock", "Bug", "Ghost",
	"Steel", "???", "Fire", "Water", "Grass", "Electric", "Psychic", "Ice", "Dragon", "Dark" }
-- Showdown stat order; the game stores HP Atk Def Spe SpA SpD (indexes 1-6 below).
local SHOWDOWN_STATS = { { 1, "HP" }, { 2, "Atk" }, { 3, "Def" }, { 5, "SpA" }, { 6, "SpD" }, { 4, "Spe" } }

-- 0x09079584: ability -> new ability, or a function of the species for the cases that test it.
local REMAP = {
	[0x02] = 0x58, [0x24] = 0x1C, [0x46] = 0x5C, [0x5A] = 0x73, [0x6D] = 0x56, [0x6F] = 0xAB,
	[0x76] = 0xC0, [0x8E] = 0x1D, [0x8F] = 0x1D, [0x99] = 0xC3, [0x9A] = 0xE5, [0x9D] = 0xC0,
	[0xAC] = 0xC0, [0xAD] = 0x27, [0xB5] = 0xE2, [0xB7] = 0xE2, [0xB8] = 0xDD, [0xC5] = 0x07,
	[0xCA] = 0x9E, [0xCF] = 0xC0, [0xD4] = 0x58, [0xD5] = 0x5C, [0xF7] = 0x5F, [0xFC] = 0x12,
	[0x03] = function(s)
		if s == 0x37B then return 0xF0 end
		if s == 0x528 or s == 0x529 then return 0x03 end
		return 0x66
	end,
	[0x2D] = function(s)
		if s == 0xF8 or s == 0x379 then return 0x16 end
		return s == 0x243 and 0x64 or 0x5F
	end,
	[0x86] = function(s) return s == 0x450 and 0x16 or 0xEB end,
	[0xB6] = function(s) return s == 0x450 and 0x16 or 0xEB end,
	[0xB0] = function(s) return s == 0x3D5 and 0xB0 or 0x1E end,
	[0xBF] = function(s) return s == 0x134 and 0xBF or 0x33 end,
}

-- Boxed Pokemon are 58 bytes, so their fields are often not 2- or 4-aligned, and mGBA's
-- read16/read32 then return the aligned value rotated (GBA bus behavior). Build every
-- multi-byte read from bytes instead.
local function u16(mem, a) return mem:read8(a) | mem:read8(a + 1) << 8 end
local function u32(mem, a) return u16(mem, a) | u16(mem, a + 2) << 16 end

local function flag(mem, id)
	return (mem:read8(EXPANDED_FLAGS + ((id - 0x900) >> 3)) >> (id & 7)) & 1 == 1
end

-- 0x09078148: pool size byte then pool entries (u8 ability IDs), restricted or normal pool.
local function random_ability(mem, ctx, ability, species)
	if flag(mem, 0x1042) or flag(mem, 0x104B) then return ability end
	local tid = math.max(1, ctx.trainer_id)
	local pool = ctx.restricted and 0x09162E06 or 0x09162ED6
	local count = mem:read8(pool)
	local secret = (tid >> 16) % 0xFF
	local i = ((tid & 0xFFFF) % count + species + ability) & 0xFFFF
	if i >= count then i = (i - count + 2) & 0xFFFF end
	i = (i ~ secret) % count
	return mem:read8(pool + 1 + i)
end

local function ability_id(mem, ctx, m)
	local b = u32(mem, BASE_STATS_PTR) + m.species * BASE_SIZE
	local a = mem:read8(b + 0x16)
	if m.hidden == 1 and mem:read8(b + 0x1A) ~= 0 then a = mem:read8(b + 0x1A)
	elseif m.personality & 1 == 1 and mem:read8(b + 0x17) ~= 0 then a = mem:read8(b + 0x17) end
	if a == 0 then return 0 end
	if ctx.randomized then a = random_ability(mem, ctx, a, m.species) end
	if ctx.restricted and m.ot_id == ctx.trainer_id then
		local r = REMAP[a]
		if type(r) == "function" then a = r(m.species) elseif r then a = r end
	end
	return a
end

local function level_from_exp(mem, species, exp)
	local rate = mem:read8(u32(mem, BASE_STATS_PTR) + species * BASE_SIZE + 0x13)
	local level = 1
	while level < MAX_LEVEL and u32(mem, EXP_TABLE + (rate * 256 + level + 1) * 4) <= exp do
		level = level + 1
	end
	return level
end

local function split_ivs(word)
	local ivs = {}
	for i = 0, 5 do ivs[i + 1] = (word >> (i * 5)) & 31 end
	return ivs
end

local function read_party_mon(mem, a)
	local species = u16(mem, a + 0x20)
	if species == 0 then return nil end
	local iv = u32(mem, a + 0x48)
	local m = {
		personality = u32(mem, a), ot_id = u32(mem, a + 4), species = species,
		item = u16(mem, a + 0x22), level = mem:read8(a + 0x54), ivs = split_ivs(iv),
		egg = (iv >> 30) & 1, hidden = (iv >> 31) & 1, moves = {}, evs = {},
	}
	for i = 1, 4 do m.moves[i] = u16(mem, a + 0x2C + (i - 1) * 2) end
	for i = 1, 6 do m.evs[i] = mem:read8(a + 0x37 + i) end
	return m
end

local function read_box_mon(mem, a)
	local species = u16(mem, a + 0x1C)
	if species == 0 then return nil end
	local iv = u32(mem, a + 0x36)
	local m = {
		personality = u32(mem, a), ot_id = u32(mem, a + 4), species = species,
		item = u16(mem, a + 0x1E), level = level_from_exp(mem, species, u32(mem, a + 0x20)),
		ivs = split_ivs(iv), egg = (iv >> 30) & 1, hidden = (iv >> 31) & 1, moves = {}, evs = {},
	}
	local packed = 0
	for i = 0, 4 do packed = packed | (mem:read8(a + 0x27 + i) << (i * 8)) end
	for i = 1, 4 do m.moves[i] = (packed >> ((i - 1) * 10)) & 0x3FF end
	for i = 1, 6 do m.evs[i] = mem:read8(a + 0x2B + i) end
	return m
end

local function hidden_power(m)
	local bits = 0
	for k = 1, 6 do bits = bits | ((m.ivs[k] & 1) << (k - 1)) end
	local t = bits * 15 // 63 + 1
	if t > 8 then t = t + 1 end
	return TYPES[t] or ("type " .. t)
end

-- Name lookups record the IDs the calc tables do not know, so the export can warn about them.
local function name(warnings, kind, list, id)
	local n = list[id]
	if not n then
		warnings[#warnings + 1] = string.format("no calc name for %s %d", kind, id)
		return string.format("%s %d", kind, id)
	end
	return n
end

local function stat_line(label, values)
	local parts = {}
	for _, s in ipairs(SHOWDOWN_STATS) do parts[#parts + 1] = values[s[1]] .. " " .. s[2] end
	return label .. ": " .. table.concat(parts, " / ")
end

local function showdown(mem, ctx, m, warnings)
	local species = name(warnings, "species", Names.species, m.species)
	-- The calc keeps female Jellicent as its own species (its RR save reader: personality low byte < 127).
	if species == "Jellicent" and m.personality & 0xFF < 127 then species = "Jellicent-F" end
	local head = species
	if m.item ~= 0 then head = head .. " @ " .. name(warnings, "item", Names.items, m.item) end
	local lines = { head }
	local a = ability_id(mem, ctx, m)
	if a ~= 0 then lines[#lines + 1] = "Ability: " .. name(warnings, "ability", Names.abilities, a) end
	lines[#lines + 1] = "Level: " .. m.level
	lines[#lines + 1] = stat_line("EVs", m.evs)
	lines[#lines + 1] = NATURES[m.personality % 25] .. " Nature"
	lines[#lines + 1] = stat_line("IVs", m.ivs)
	for i = 1, 4 do
		if m.moves[i] ~= 0 then lines[#lines + 1] = "- " .. name(warnings, "move", Names.moves, m.moves[i]) end
	end
	return table.concat(lines, "\n") .. "\n"
end

-- Returns the Showdown text, the Hidden Power lines, the warnings and the Pokemon count.
local function build(mem)
	local sb2 = u32(mem, SAVE_BLOCK2_PTR)
	local ctx = {
		trainer_id = u32(mem, sb2 + 0xA),
		randomized = flag(mem, 0x942) and not flag(mem, 0x930),
		restricted = flag(mem, 0x1034) or flag(mem, 0x103C),
	}
	local mons = {}
	for slot = 0, 5 do
		local m = read_party_mon(mem, PARTY + slot * PARTY_SIZE)
		if m then m.where = "party " .. (slot + 1); mons[#mons + 1] = m end
	end
	for box = 0, BOX_COUNT - 1 do
		local base = u32(mem, BOX_PTRS + box * 4)
		for slot = 0, BOX_SLOTS - 1 do
			local m = read_box_mon(mem, base + slot * BOX_MON_SIZE)
			if m then m.where = string.format("box %d slot %d", box + 1, slot + 1); mons[#mons + 1] = m end
		end
	end
	local text, hp, warnings = {}, {}, {}
	for _, m in ipairs(mons) do
		if m.egg == 0 then
			local w = #warnings
			text[#text + 1] = showdown(mem, ctx, m, warnings)
			for i = w + 1, #warnings do warnings[i] = m.where .. ": " .. warnings[i] end
			hp[#hp + 1] = string.format("%-12s %-20s %s", m.where, Names.species[m.species] or m.species, hidden_power(m))
		end
	end
	local mode = {}
	if ctx.randomized then mode[#mode + 1] = "randomized abilities" end
	if ctx.restricted then mode[#mode + 1] = "ability remap (flag 0x1034/0x103C)" end
	return table.concat(text, "\n"), hp, warnings, #text, mode
end

RRShowdown = { build = build, ability_id = ability_id, level_from_exp = level_from_exp }

local export_buffer, hp_buffer, help_buffer
local OUT = os.getenv("RR_SHOWDOWN_OUT") or (SCRIPT_DIR .. "logs/showdown.txt")

function export()
	local ok, text, hp, warnings, count, mode = pcall(build, emu)
	if not ok then
		console:log("[showdown] export failed: " .. tostring(text))
		return
	end
	-- A text buffer keeps only as many rows as its size; grow it so the whole export stays visible.
	local _, rows = text:gsub("\n", "")
	export_buffer:setSize(100, rows + 10)
	hp_buffer:setSize(100, #hp + 10)
	export_buffer:clear()
	export_buffer:print(text)
	hp_buffer:clear()
	hp_buffer:print(table.concat(hp, "\n") .. "\n")
	local f = io.open(OUT, "w")
	if f then f:write(text); f:close() end
	local note = string.format("[showdown] exported %d Pokemon%s%s", count,
		#mode > 0 and (" (" .. table.concat(mode, ", ") .. ")") or "",
		f and (" to " .. OUT) or (", cannot write " .. OUT))
	console:log(note)
	for _, w in ipairs(warnings) do console:log("[showdown] " .. w) end
end

local function start()
	if not export_buffer then
		export_buffer = console:createBuffer("Showdown Export")
		hp_buffer = console:createBuffer("Hidden Powers")
		help_buffer = console:createBuffer("Help")
		help_buffer:print("Type export() in the scripting console to refresh the Showdown Export and\n"
			.. "Hidden Powers tabs. The export is also written to " .. OUT .. ".\n"
			.. "Paste it into the calc's import box (Radical Red data set).\n")
	end
	export()
end

callbacks:add("start", start)
if emu then start() end
